import java.util.Scanner;

public class Calculator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double first = scanner.nextDouble();
        char operator = scanner.next().charAt(0);
        double second = scanner.nextDouble();
        double result = switch (operator) {
            case '+' -> first + second;
            case '-' -> first - second;
            case '*' -> first * second;
            case '/' -> second == 0 ? Double.NaN : first / second;
            default -> Double.NaN;
        };
        System.out.println(result);
        scanner.close();
    }
}

import java.util.Random;
import java.util.Scanner;

public class GuessingGame {
    public static void main(String[] args) {
        int target = new Random().nextInt(100) + 1;
        Scanner scanner = new Scanner(System.in);
        int guess;
        do {
            guess = scanner.nextInt();
            if (guess < target) System.out.println("Higher");
            else if (guess > target) System.out.println("Lower");
        } while (guess != target);
        System.out.println("Correct");
        scanner.close();
    }
}

public class BasicChecks {
    static boolean isPalindrome(String value) {
        int left = 0;
        int right = value.length() - 1;
        while (left < right) {
            if (value.charAt(left++) != value.charAt(right--)) return false;
        }
        return true;
    }

    static boolean isPrime(int number) {
        if (number < 2) return false;
        for (int divisor = 2; divisor * divisor <= number; divisor++) {
            if (number % divisor == 0) return false;
        }
        return true;
    }
}
